static int32_t zen_platform_host_os(void){
#if defined(__APPLE__)
return 1;
#elif defined(__linux__)
return 2;
#elif defined(_WIN32)
return 3;
#elif defined(__FreeBSD__)
return 4;
#else
return 0;
#endif
}
static int32_t zen_platform_host_arch(void){
#if defined(__aarch64__) || defined(_M_ARM64)
return 1;
#elif defined(__x86_64__) || defined(_M_X64)
return 2;
#elif defined(__riscv) && __riscv_xlen == 64
return 3;
#elif defined(__wasm32__)
return 4;
#else
return 0;
#endif
}
static int32_t zen_platform_host_abi(void){
#if defined(__APPLE__)
return 1;
#elif defined(__linux__) && defined(__GLIBC__)
return 2;
#elif defined(__linux__)
return 3;
#elif defined(_MSC_VER)
return 4;
#elif defined(__wasi__)
return 5;
#else
return 0;
#endif
}
